-- University planner, HR & payroll, student fees, accounting, admission CRM, inventory & purchasing. Safe to run more than once.
CREATE TABLE IF NOT EXISTS "UniPlan" ("id" TEXT PRIMARY KEY, "chairmanId" TEXT NOT NULL, "title" TEXT NOT NULL, "area" TEXT, "ownerId" TEXT, "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "UniPlan_chairmanId_idx" ON "UniPlan" ("chairmanId");
CREATE TABLE IF NOT EXISTS "PayStructure" ("userId" TEXT PRIMARY KEY, "basic" DOUBLE PRECISION NOT NULL DEFAULT 0, "allowancesJson" TEXT NOT NULL DEFAULT '[]', "deductionsJson" TEXT NOT NULL DEFAULT '[]', "taxPct" DOUBLE PRECISION NOT NULL DEFAULT 0, "bank" TEXT, "account" TEXT, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "PayrollRun" ("id" TEXT PRIMARY KEY, "chairmanId" TEXT NOT NULL, "month" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'DRAFT', "totalsJson" TEXT NOT NULL DEFAULT '{}', "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS "PayrollRun_chairmanId_month_key" ON "PayrollRun" ("chairmanId", "month");
CREATE TABLE IF NOT EXISTS "Payslip" ("id" TEXT PRIMARY KEY, "runId" TEXT NOT NULL, "userId" TEXT NOT NULL, "gross" DOUBLE PRECISION NOT NULL, "deductions" DOUBLE PRECISION NOT NULL, "tax" DOUBLE PRECISION NOT NULL, "net" DOUBLE PRECISION NOT NULL, "linesJson" TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS "Payslip_runId_idx" ON "Payslip" ("runId");
CREATE TABLE IF NOT EXISTS "FeeInvoice" ("id" TEXT PRIMARY KEY, "chairmanId" TEXT NOT NULL, "studentId" TEXT NOT NULL, "termName" TEXT NOT NULL, "termYear" INTEGER NOT NULL, "linesJson" TEXT NOT NULL, "amount" DOUBLE PRECISION NOT NULL, "discount" DOUBLE PRECISION NOT NULL DEFAULT 0, "fine" DOUBLE PRECISION NOT NULL DEFAULT 0, "paid" DOUBLE PRECISION NOT NULL DEFAULT 0, "dueDate" TIMESTAMP(3) NOT NULL, "status" TEXT NOT NULL DEFAULT 'UNPAID', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "FeeInvoice_chairmanId_idx" ON "FeeInvoice" ("chairmanId");
CREATE INDEX IF NOT EXISTS "FeeInvoice_studentId_idx" ON "FeeInvoice" ("studentId");
CREATE TABLE IF NOT EXISTS "FeePayment" ("id" TEXT PRIMARY KEY, "invoiceId" TEXT NOT NULL, "amount" DOUBLE PRECISION NOT NULL, "method" TEXT NOT NULL, "reference" TEXT, "paidAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "receivedById" TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS "FeePayment_invoiceId_idx" ON "FeePayment" ("invoiceId");
CREATE TABLE IF NOT EXISTS "LedgerAccount" ("id" TEXT PRIMARY KEY, "chairmanId" TEXT NOT NULL, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "type" TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "LedgerAccount_chairmanId_code_key" ON "LedgerAccount" ("chairmanId", "code");
CREATE TABLE IF NOT EXISTS "JournalEntry" ("id" TEXT PRIMARY KEY, "chairmanId" TEXT NOT NULL, "date" TIMESTAMP(3) NOT NULL, "memo" TEXT NOT NULL, "source" TEXT, "sourceId" TEXT, "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "JournalEntry_chairmanId_date_idx" ON "JournalEntry" ("chairmanId", "date");
CREATE TABLE IF NOT EXISTS "JournalLine" ("id" TEXT PRIMARY KEY, "entryId" TEXT NOT NULL, "accountId" TEXT NOT NULL, "debit" DOUBLE PRECISION NOT NULL DEFAULT 0, "credit" DOUBLE PRECISION NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS "JournalLine_entryId_idx" ON "JournalLine" ("entryId");
CREATE INDEX IF NOT EXISTS "JournalLine_accountId_idx" ON "JournalLine" ("accountId");
CREATE TABLE IF NOT EXISTS "AdmissionLead" ("id" TEXT PRIMARY KEY, "chairmanId" TEXT NOT NULL, "name" TEXT NOT NULL, "phone" TEXT, "email" TEXT, "city" TEXT, "program" TEXT, "source" TEXT, "stage" TEXT NOT NULL DEFAULT 'INQUIRY', "score" DOUBLE PRECISION, "ownerId" TEXT, "nextFollowUp" TIMESTAMP(3), "notes" TEXT, "studentId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "AdmissionLead_chairmanId_stage_idx" ON "AdmissionLead" ("chairmanId", "stage");
CREATE TABLE IF NOT EXISTS "LeadActivity" ("id" TEXT PRIMARY KEY, "leadId" TEXT NOT NULL, "kind" TEXT NOT NULL, "text" TEXT NOT NULL, "byId" TEXT NOT NULL, "at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "LeadActivity_leadId_idx" ON "LeadActivity" ("leadId");
CREATE TABLE IF NOT EXISTS "Vendor" ("id" TEXT PRIMARY KEY, "chairmanId" TEXT NOT NULL, "name" TEXT NOT NULL, "phone" TEXT, "email" TEXT, "ntn" TEXT, "address" TEXT);
CREATE INDEX IF NOT EXISTS "Vendor_chairmanId_idx" ON "Vendor" ("chairmanId");
CREATE TABLE IF NOT EXISTS "StockItem" ("id" TEXT PRIMARY KEY, "chairmanId" TEXT NOT NULL, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "category" TEXT, "unit" TEXT NOT NULL DEFAULT 'pcs', "location" TEXT, "qty" DOUBLE PRECISION NOT NULL DEFAULT 0, "reorderLevel" DOUBLE PRECISION NOT NULL DEFAULT 0, "unitCost" DOUBLE PRECISION NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX IF NOT EXISTS "StockItem_chairmanId_code_key" ON "StockItem" ("chairmanId", "code");
CREATE TABLE IF NOT EXISTS "StockMove" ("id" TEXT PRIMARY KEY, "itemId" TEXT NOT NULL, "qty" DOUBLE PRECISION NOT NULL, "kind" TEXT NOT NULL, "ref" TEXT, "byId" TEXT NOT NULL, "at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "StockMove_itemId_idx" ON "StockMove" ("itemId");
CREATE TABLE IF NOT EXISTS "PurchaseRequest" ("id" TEXT PRIMARY KEY, "chairmanId" TEXT NOT NULL, "requestedById" TEXT NOT NULL, "title" TEXT NOT NULL, "linesJson" TEXT NOT NULL, "total" DOUBLE PRECISION NOT NULL DEFAULT 0, "status" TEXT NOT NULL DEFAULT 'REQUESTED', "vendorId" TEXT, "poNumber" TEXT, "decidedById" TEXT, "note" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "PurchaseRequest_chairmanId_status_idx" ON "PurchaseRequest" ("chairmanId", "status");
SELECT 'done' AS result;
